/**
 * Asset Check-in API Route
 * POST /api/assets/[id]/checkin - Check in an asset
 */

import { NextRequest, NextResponse } from 'next/server';
import { revalidatePath } from 'next/cache';
import { assignmentService } from '@/modules/assets/services';

interface RouteParams {
  params: Promise<{ id: string }>;
}

// ==================== POST /api/assets/[id]/checkin ====================

export async function POST(req: NextRequest, { params }: RouteParams) {
  try {
    const { id: assetId } = await params;
    const body = await req.json();

    // Get the active assignment for this asset
    const activeResult = await assignmentService.getActiveAssignment(assetId);

    if (!activeResult.success || !activeResult.data) {
      return NextResponse.json(
        { error: 'No active assignment found for this asset' },
        { status: 404 }
      );
    }

    const assignmentId = activeResult.data.id;

    // Prepare checkin data
    const checkinData = {
      assignmentId,
      conditionAtCheckin: body.conditionAtCheckin || 'good',
      checkinNotes: body.checkinNotes,
      newLocation: body.newLocation,
      maintenanceRequired: body.maintenanceRequired || false,
    };

    // Authenticate request (user identity from JWT, never from client headers)
    const [user, unauth] = await requireAuth(req);
    if (unauth) return unauth;

    const checkedInBy = user.id;

    const result = await assignmentService.checkin(checkinData, checkedInBy);

    if (!result.success) {
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    // Revalidate asset pages (checkin changes assigned → available counts)
    revalidatePath('/assets');
    revalidatePath('/assets/list');
    revalidatePath(`/assets/${assetId}`);

    return NextResponse.json({
      data: result.data,
      message: 'Asset checked in successfully'
    }, { status: 200 });
  } catch (error) {
    console.error('Error checking in asset:', error);
    return NextResponse.json(
      { error: 'Failed to check in asset' },
      { status: 500 }
    );
  }
}

/**
 * Asset Checkout API Route
 * POST /api/assets/[id]/checkout - Checkout an asset
 */

import { NextRequest, NextResponse } from 'next/server';
import { revalidatePath } from 'next/cache';
import { assignmentService } from '@/modules/assets/services';
import { CheckoutAssetSchema } from '@/modules/assets/utils/schemas';

interface RouteParams {
  params: Promise<{ id: string }>;
}

// ==================== POST /api/assets/[id]/checkout ====================

export async function POST(req: NextRequest, { params }: RouteParams) {
  try {
    const { id } = await params;
    const body = await req.json();

    // Add asset ID from URL to body
    const checkoutData = { ...body, assetId: id };

    // Validate request body
    const validation = CheckoutAssetSchema.safeParse(checkoutData);
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: validation.error.errors },
        { status: 400 }
      );
    }

    // Authenticate request (user identity from JWT, never from client headers)
    const [user, unauth] = await requireAuth(req);
    if (unauth) return unauth;

    const createdBy = user.id;

    const result = await assignmentService.checkout(validation.data, createdBy);

    if (!result.success) {
      if (result.error?.includes('not found')) {
        return NextResponse.json({ error: result.error }, { status: 404 });
      }
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    // Revalidate asset pages (checkout changes available → assigned counts)
    revalidatePath('/assets');
    revalidatePath('/assets/list');
    revalidatePath(`/assets/${id}`);

    return NextResponse.json({ data: result.data }, { status: 201 });
  } catch (error) {
    console.error('Error checking out asset:', error);
    return NextResponse.json(
      { error: 'Failed to checkout asset' },
      { status: 500 }
    );
  }
}

/**
 * Asset Documents API Route
 * GET  /api/assets/[id]/documents - List documents for an asset
 * POST /api/assets/[id]/documents - Upload a document
 */

import { NextRequest, NextResponse } from 'next/server';
import { getDbConnection } from '@/modules/assets/utils/db';
import { v4 as uuidv4 } from 'uuid';

interface RouteParams {
  params: Promise<{ id: string }>;
}

// ==================== GET /api/assets/[id]/documents ====================

export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const { id: assetId } = await params;
    const sql = getDbConnection();

    const documents = await sql`
      SELECT
        id,
        asset_id as "assetId",
        maintenance_id as "maintenanceId",
        document_type as "documentType",
        document_name as "documentName",
        document_number as "documentNumber",
        file_name as "fileName",
        file_path as "filePath",
        file_url as "fileUrl",
        file_size as "fileSize",
        mime_type as "mimeType",
        issue_date as "issueDate",
        expiry_date as "expiryDate",
        issuing_authority as "issuingAuthority",
        issuer_contact as "issuerContact",
        is_active as "isActive",
        notes,
        uploaded_by as "uploadedBy",
        created_at as "createdAt",
        updated_at as "updatedAt"
      FROM asset_documents
      WHERE asset_id = ${assetId}
        AND is_active = true
      ORDER BY created_at DESC
    `;

    return NextResponse.json({ data: documents });
  } catch (error) {
    console.error('Error fetching documents:', error);
    return NextResponse.json(
      { error: 'Failed to fetch documents' },
      { status: 500 }
    );
  }
}

// ==================== POST /api/assets/[id]/documents ====================

export async function POST(req: NextRequest, { params }: RouteParams) {
  try {
    const { id: assetId } = await params;
    const sql = getDbConnection();

    // Check if asset exists
    const [asset] = await sql`SELECT id FROM assets WHERE id = ${assetId}`;
    if (!asset) {
      return NextResponse.json({ error: 'Asset not found' }, { status: 404 });
    }

    const body = await req.json();
    const {
      documentType,
      documentName,
      documentNumber,
      fileName,
      filePath,
      fileUrl,
      fileSize,
      mimeType,
      issueDate,
      expiryDate,
      issuingAuthority,
      issuerContact,
      notes,
      maintenanceId,
    } = body;

    // Validate required fields
    if (!documentType || !documentName || !fileUrl) {
      return NextResponse.json(
        { error: 'documentType, documentName, and fileUrl are required' },
        { status: 400 }
      );
    }

    const id = uuidv4();
    const [user, unauth] = await requireAuth(req);
    if (unauth) return unauth;

    const uploadedBy = user.id;

    const [document] = await sql`
      INSERT INTO asset_documents (
        id,
        asset_id,
        maintenance_id,
        document_type,
        document_name,
        document_number,
        file_name,
        file_path,
        file_url,
        file_size,
        mime_type,
        issue_date,
        expiry_date,
        issuing_authority,
        issuer_contact,
        is_active,
        notes,
        uploaded_by,
        created_at,
        updated_at
      ) VALUES (
        ${id},
        ${assetId},
        ${maintenanceId || null},
        ${documentType},
        ${documentName},
        ${documentNumber || null},
        ${fileName || null},
        ${filePath || null},
        ${fileUrl},
        ${fileSize || null},
        ${mimeType || null},
        ${issueDate ? new Date(issueDate) : null},
        ${expiryDate ? new Date(expiryDate) : null},
        ${issuingAuthority || null},
        ${issuerContact || null},
        true,
        ${notes || null},
        ${uploadedBy},
        NOW(),
        NOW()
      )
      RETURNING
        id,
        asset_id as "assetId",
        document_type as "documentType",
        document_name as "documentName",
        file_url as "fileUrl",
        created_at as "createdAt"
    `;

    return NextResponse.json({ data: document }, { status: 201 });
  } catch (error) {
    console.error('Error creating document:', error);
    return NextResponse.json(
      { error: 'Failed to create document' },
      { status: 500 }
    );
  }
}

/**
 * Single Asset API Route
 * GET    /api/assets/[id] - Get asset by ID
 * PUT    /api/assets/[id] - Update asset
 * DELETE /api/assets/[id] - Delete asset
 */

import { NextRequest, NextResponse } from 'next/server';
import { revalidatePath } from 'next/cache';
import { assetService } from '@/modules/assets/services';
import { UpdateAssetSchema } from '@/modules/assets/utils/schemas';

interface RouteParams {
  params: Promise<{ id: string }>;
}

// ==================== GET /api/assets/[id] ====================

export async function GET(req: NextRequest, { params }: RouteParams) {
  try {
    const { id } = await params;

    const result = await assetService.getById(id);

    if (!result.success) {
      return NextResponse.json({ error: result.error }, { status: 500 });
    }

    if (!result.data) {
      return NextResponse.json({ error: 'Asset not found' }, { status: 404 });
    }

    return NextResponse.json({ data: result.data });
  } catch (error) {
    console.error('Error fetching asset:', error);
    return NextResponse.json(
      { error: 'Failed to fetch asset' },
      { status: 500 }
    );
  }
}

// ==================== PUT /api/assets/[id] ====================

export async function PUT(req: NextRequest, { params }: RouteParams) {
  try {
    const { id } = await params;
    const body = await req.json();

    // Validate request body
    const validation = UpdateAssetSchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: validation.error.errors },
        { status: 400 }
      );
    }

    // Authenticate request (user identity from JWT, never from client headers)
    const [user, unauth] = await requireAuth(req);
    if (unauth) return unauth;

    const updatedBy = user.id;

    const result = await assetService.update(id, validation.data, updatedBy);

    if (!result.success) {
      if (result.error === 'Asset not found') {
        return NextResponse.json({ error: result.error }, { status: 404 });
      }
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    // Revalidate asset pages (status changes affect counts)
    revalidatePath('/assets');
    revalidatePath('/assets/list');
    revalidatePath(`/assets/${id}`);

    return NextResponse.json({ data: result.data });
  } catch (error) {
    console.error('Error updating asset:', error);
    return NextResponse.json(
      { error: 'Failed to update asset' },
      { status: 500 }
    );
  }
}

// ==================== DELETE /api/assets/[id] ====================

export async function DELETE(req: NextRequest, { params }: RouteParams) {
  try {
    const { id } = await params;

    const result = await assetService.delete(id);

    if (!result.success) {
      if (result.error === 'Asset not found') {
        return NextResponse.json({ error: result.error }, { status: 404 });
      }
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    // Revalidate asset pages to update counts
    revalidatePath('/assets');
    revalidatePath('/assets/list');

    return NextResponse.json({ success: true }, { status: 200 });
  } catch (error) {
    console.error('Error deleting asset:', error);
    return NextResponse.json(
      { error: 'Failed to delete asset' },
      { status: 500 }
    );
  }
}

